// 依權重隨機挑選一隻怪物（權重越高越容易遇到，對應真實地圖的怪物密度）





function pickWeightedMonster(pool) {
  const total = pool.reduce((s, m) => s + m.weight, 0);
  let r = Math.random() * total;
  for (const m of pool) {
    if (r < m.weight) return m.id;
    r -= m.weight;
  }
  return pool[pool.length - 1].id;
}




function mapImgSrc(mapId) {
  const m = MAPS.find(x => x.id === mapId);
  return resolveImgPath(`maps/${m.imgId}.png`);
}



const MUSIC_EXTS = ['mp3', 'ogg', 'wav'];


